function parseRecipients(value: string): string[] {
  try {
    const parsed: unknown = JSON.parse(value);
    return Array.isArray(parsed) &&
      parsed.every((recipient) => typeof recipient === "string")
      ? parsed
      : [];
  } catch {
    return [];
  }
}

