      "CREATE INDEX IF NOT EXISTS readings_register_time_idx ON readings(register_id, timestamp DESC)",
      "CREATE INDEX IF NOT EXISTS readings_register_id_idx ON readings(register_id, id DESC)",
      "CREATE INDEX IF NOT EXISTS readings_device_time_idx ON readings(device_id, timestamp DESC)",
