  recordPostgresConnectionTest(ok: boolean, message: string): void {
    this.connection
      .prepare(
        `UPDATE postgres_settings
         SET last_connection_test_at = ?, last_connection_test_ok = ?,
             last_connection_test_message = ?, updated_at = ?
         WHERE id = 1`,
      )
      .run(
        new Date().toISOString(),
        ok ? 1 : 0,
        message.slice(0, 500),
        new Date().toISOString(),
      );
  }

  recordPostgresMaintenance(
    rawDeleted: number,
    downsampleDeleted: number,
  ): void {
    this.connection
      .prepare(
        `UPDATE postgres_settings
         SET last_maintenance_at = ?,
             last_maintenance_raw_deleted = ?,
             last_maintenance_downsample_deleted = ?,
             updated_at = ?
         WHERE id = 1`,
      )
      .run(
        new Date().toISOString(),
        rawDeleted,
        downsampleDeleted,
        new Date().toISOString(),
      );
  }

  recordPostgresReplay(
    count: number,
    completedAt = new Date().toISOString(),
  ): void {
    this.connection
      .prepare(
        `UPDATE postgres_settings
         SET last_replay_at = ?, last_replay_count = ?, updated_at = ?
         WHERE id = 1`,
      )
      .run(completedAt, count, completedAt);
  }

  enqueuePostgresOutbox(
    deviceId: string,
    sampleTimestamp: string,
    saveBucketMs: number,
    readings: ReadingInsert[],
    maxRows: number,
  ): { queued: boolean; dropped: number } {
    return this.connection.transaction(() => {
      const existing = this.connection
        .prepare(
          `SELECT id, sample_timestamp
           FROM postgres_outbox
           WHERE device_id = ? AND save_bucket_ms = ?`,
        )
        .get(deviceId, saveBucketMs) as
        { id: number; sample_timestamp: string } | undefined;

      let queued = false;
      if (!existing || sampleTimestamp >= existing.sample_timestamp) {
        this.connection
          .prepare(
            `DELETE FROM postgres_outbox
             WHERE device_id = ? AND sample_timestamp = ?
               AND save_bucket_ms <> ?`,
          )
          .run(deviceId, sampleTimestamp, saveBucketMs);
        this.connection
          .prepare(
            `INSERT INTO postgres_outbox (
               device_id, sample_timestamp, save_bucket_ms, readings_json,
               created_at
             ) VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(device_id, save_bucket_ms) DO UPDATE SET
               sample_timestamp = excluded.sample_timestamp,
               readings_json = excluded.readings_json`,
          )
          .run(
            deviceId,
            sampleTimestamp,
            saveBucketMs,
            JSON.stringify(readings),
            new Date().toISOString(),
          );
        queued = true;
      }

      const dropped = this.trimPostgresOutbox(maxRows);
      return { queued, dropped };
    })();
  }

  trimPostgresOutbox(maxRows: number): number {
    const total = (
      this.connection
        .prepare("SELECT COUNT(*) AS count FROM postgres_outbox")
        .get() as CountRow
    ).count;
    const overflow = Math.max(0, total - maxRows);
    if (overflow === 0) return 0;
    const deleted = this.connection
      .prepare(
        `DELETE FROM postgres_outbox
         WHERE id IN (
           SELECT id FROM postgres_outbox
           ORDER BY sample_timestamp ASC, id ASC
           LIMIT ?
         )`,
      )
      .run(overflow).changes;

    if (deleted > 0) {
      this.appendActivity({
        level: "warning",
        category: "system",
        event: "samples_dropped",
        message: `Dropped ${deleted} outbox sample(s) to stay within maxRows limit (${maxRows})`,
        details: { dropped: deleted, maxRows },
      });
    }

    return deleted;
  }

