  observeSystemAlert(input: {
    type: SystemAlertType;
    sourceKey: string;
    sourceId: string | null;
    sourceName: string;
    offline: boolean;
    detail: string;
    offlineDelaySeconds: number;
    deliveryRecipients?: string[];
    sendRecovery?: boolean;
    observedAt?: string;
  }): SystemAlertTransition {
    return this.connection.transaction(() => {
      const observedAt = input.observedAt ?? new Date().toISOString();
      const active = this.connection
        .prepare(
          `SELECT *
           FROM system_alerts
           WHERE alert_type = ? AND source_key = ? AND resolved_at IS NULL
           ORDER BY opened_at DESC
           LIMIT 1`,
        )
        .get(input.type, input.sourceKey) as SystemAlertRow | undefined;

      if (!input.offline) {
        this.connection
          .prepare("DELETE FROM system_alert_observations WHERE source_key = ?")
          .run(input.sourceKey);
        if (!active) return { opened: null, resolved: null };
        this.connection
          .prepare(
            `UPDATE system_alerts
             SET resolved_at = ?, resolution_detail = ?,
                 last_observed_at = ?
             WHERE id = ? AND resolved_at IS NULL`,
          )
          .run(observedAt, input.detail.slice(0, 1000), observedAt, active.id);
        const acceptedRecipients = (
          this.connection
            .prepare(
              `SELECT recipient
               FROM system_alert_deliveries
               WHERE alert_id = ? AND event_kind = 'opened'
                 AND status = 'sent'`,
            )
            .all(active.id) as Array<{ recipient: string }>
        ).map((row) => row.recipient);
        this.connection
          .prepare(
            `DELETE FROM system_alert_deliveries
             WHERE alert_id = ? AND event_kind = 'opened'
               AND status IN ('pending', 'failed')`,
          )
          .run(active.id);
        if (input.sendRecovery) {
          const configuredRecipients = new Set(input.deliveryRecipients ?? []);
          this.enqueueSystemAlertDeliveries(
            active.id,
            "recovery",
            acceptedRecipients.filter((recipient) =>
              configuredRecipients.has(recipient),
            ),
            observedAt,
          );
        }
        this.appendActivity({
          timestamp: observedAt,
          level: "info",
          category: "system",
          event: "system_alert.resolved",
          message: `${input.sourceName} recovered`,
          entityType: "system_alert",
          entityId: active.id,
          details: {
            type: input.type,
            sourceId: input.sourceId,
            sourceName: input.sourceName,
            detail: input.detail,
          },
        });
        return {
          opened: null,
          resolved: {
            id: active.id,
            type: active.alert_type,
            sourceName: input.sourceName,
            detail: input.detail.slice(0, 1000),
            occurredAt: observedAt,
          },
        };
      }

      const observation = this.connection
        .prepare(
          `SELECT offline_since
           FROM system_alert_observations
           WHERE source_key = ?`,
        )
        .get(input.sourceKey) as { offline_since: string } | undefined;
      const offlineSince = observation?.offline_since ?? observedAt;
      this.connection
        .prepare(
          `INSERT INTO system_alert_observations (
             source_key, alert_type, source_id, source_name, offline_since,
             detail, last_observed_at
           ) VALUES (?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT(source_key) DO UPDATE SET
             alert_type = excluded.alert_type,
             source_id = excluded.source_id,
             source_name = excluded.source_name,
             detail = excluded.detail,
             last_observed_at = excluded.last_observed_at`,
        )
        .run(
          input.sourceKey,
          input.type,
          input.sourceId,
          input.sourceName.slice(0, 250),
          offlineSince,
          input.detail.slice(0, 1000),
          observedAt,
        );

      if (active) {
        this.connection
          .prepare(
            `UPDATE system_alerts
             SET source_id = ?, source_name = ?, detail = ?,
                 last_observed_at = ?
             WHERE id = ?`,
          )
          .run(
            input.sourceId,
            input.sourceName.slice(0, 250),
            input.detail.slice(0, 1000),
            observedAt,
            active.id,
          );
        return { opened: null, resolved: null };
      }

      const offlineSinceMs = Date.parse(offlineSince);
      const observedAtMs = Date.parse(observedAt);
      if (
        !Number.isFinite(offlineSinceMs) ||
        !Number.isFinite(observedAtMs) ||
        observedAtMs - offlineSinceMs < input.offlineDelaySeconds * 1000
      ) {
        return { opened: null, resolved: null };
      }

      const id = createId("sysalm");
      this.connection
        .prepare(
          `INSERT INTO system_alerts (
             id, alert_type, source_key, source_id, source_name, severity,
             detail, opened_at, last_observed_at
           ) VALUES (?, ?, ?, ?, ?, 'critical', ?, ?, ?)`,
        )
        .run(
          id,
          input.type,
          input.sourceKey,
          input.sourceId,
          input.sourceName.slice(0, 250),
          input.detail.slice(0, 1000),
          offlineSince,
          observedAt,
        );
      this.enqueueSystemAlertDeliveries(
        id,
        "opened",
        input.deliveryRecipients ?? [],
        observedAt,
      );
      this.appendActivity({
        timestamp: observedAt,
        level: "error",
        category: "system",
        event: "system_alert.opened",
        message: `${input.sourceName} is offline`,
        entityType: "system_alert",
        entityId: id,
        details: {
          type: input.type,
          sourceId: input.sourceId,
          sourceName: input.sourceName,
          detail: input.detail,
        },
      });
      return {
        opened: {
          id,
          type: input.type,
          sourceName: input.sourceName,
          detail: input.detail.slice(0, 1000),
          occurredAt: offlineSince,
        },
        resolved: null,
      };
    })();
  }

  private enqueueSystemAlertDeliveries(
    alertId: string,
    eventKind: "opened" | "recovery",
    recipients: string[],
    createdAt: string,
  ): void {
    const insert = this.connection.prepare(
      `INSERT OR IGNORE INTO system_alert_deliveries (
         alert_id, channel, event_kind, recipient, status, attempts,
         next_attempt_at, created_at
       ) VALUES (?, 'whatsapp', ?, ?, 'pending', 0, ?, ?)`,
    );
    for (const recipient of new Set(recipients)) {
      insert.run(alertId, eventKind, recipient, createdAt, createdAt);
    }
  }

  listSystemAlerts(options: {
    activeOnly: boolean;
    limit: number;
  }): SystemAlert[] {
    const activeClause = options.activeOnly
      ? "WHERE alert.resolved_at IS NULL"
      : "";
    const rows = this.connection
      .prepare(
        `SELECT
           alert.*,
           user.username AS acknowledged_by_username,
           CASE
             WHEN EXISTS (
               SELECT 1 FROM system_alert_deliveries AS delivery
               WHERE delivery.alert_id = alert.id
                 AND delivery.status IN ('failed', 'dead')
             ) THEN 'failed'
             WHEN EXISTS (
               SELECT 1 FROM system_alert_deliveries AS delivery
               WHERE delivery.alert_id = alert.id
                 AND delivery.status = 'pending'
             ) THEN 'pending'
             WHEN EXISTS (
               SELECT 1 FROM system_alert_deliveries AS delivery
               WHERE delivery.alert_id = alert.id
                 AND delivery.status = 'sent'
             ) THEN 'sent'
             ELSE 'not_configured'
           END AS delivery_status
         FROM system_alerts AS alert
         LEFT JOIN users AS user ON user.id = alert.acknowledged_by
         ${activeClause}
         ORDER BY alert.opened_at DESC
         LIMIT ?`,
      )
      .all(options.limit) as SystemAlertRow[];
    return rows.map(mapSystemAlert);
  }

