  listDueSystemAlertDeliveries(
    limit: number,
    now = new Date().toISOString(),
  ): SystemAlertDelivery[] {
    const rows = this.connection
      .prepare(
        `SELECT
           delivery.id, delivery.alert_id, delivery.event_kind,
           delivery.recipient, delivery.attempts, alert.alert_type,
           alert.source_name,
           CASE
             WHEN delivery.event_kind = 'recovery'
               THEN COALESCE(alert.resolution_detail, 'Connection recovered')
             ELSE alert.detail
           END AS detail
         FROM system_alert_deliveries AS delivery
         JOIN system_alerts AS alert ON alert.id = delivery.alert_id
         WHERE delivery.status IN ('pending', 'failed')
           AND delivery.next_attempt_at <= ?
         ORDER BY delivery.next_attempt_at, delivery.id
         LIMIT ?`,
      )
      .all(now, limit) as Array<{
      id: number;
      alert_id: string;
      alert_type: SystemAlertType;
      source_name: string;
      detail: string;
      event_kind: "opened" | "recovery";
      recipient: string;
      attempts: number;
    }>;
    return rows.map((row) => ({
      id: row.id,
      alertId: row.alert_id,
      alertType: row.alert_type,
      sourceName: row.source_name,
      detail: row.detail,
      eventKind: row.event_kind,
      recipient: row.recipient,
      attempts: row.attempts,
    }));
  }

