  markSystemAlertDeliveryDead(id: number, message: string): void {
    this.connection
      .prepare(
        `UPDATE system_alert_deliveries
         SET status = 'dead', attempts = attempts + 1,
             last_attempt_at = ?, last_error = ?, next_attempt_at = ?
         WHERE id = ?`,
      )
      .run(
        new Date().toISOString(),
        message.slice(0, 500),
        "9999-12-31T23:59:59.999Z",
        id,
      );
  }

  cancelUnsentSystemAlertDeliveries(recipients: string[] | null): number {
    if (recipients === null || recipients.length === 0) {
      return this.connection
        .prepare(
          `DELETE FROM system_alert_deliveries
           WHERE status IN ('pending', 'failed')`,
        )
        .run().changes;
    }
    const placeholders = recipients.map(() => "?").join(", ");
    return this.connection
      .prepare(
        `DELETE FROM system_alert_deliveries
         WHERE status IN ('pending', 'failed')
           AND recipient NOT IN (${placeholders})`,
      )
      .run(...recipients).changes;
  }

