  createUser(input: {
    username: string;
    passwordHash: string;
    role: UserRole;
    enabled?: boolean;
  }): UserSummary {
    const id = createId("usr");
    const createdAt = new Date().toISOString();
    this.connection
      .prepare(
        `INSERT INTO users (id, username, password_hash, role, enabled, created_at)
         VALUES (?, ?, ?, ?, ?, ?)`,
      )
      .run(
        id,
        input.username,
        input.passwordHash,
        input.role,
        input.enabled === false ? 0 : 1,
        createdAt,
      );
    return mapUser(this.getUserById(id) as UserRow);
  }

  updateUser(
    id: string,
    input: {
      username?: string;
      role?: UserRole;
      enabled?: boolean;
    },
    actorId: string,
  ): UserSummary | undefined {
    return this.connection.transaction(() => {
      const existing = this.getUserById(id);
      if (!existing) return undefined;
      const nextRole = input.role ?? existing.role;
      const nextEnabled =
        input.enabled === undefined ? Boolean(existing.enabled) : input.enabled;
      if (id === actorId && !nextEnabled) {
        throw new UserAdministrationError(
          "self_protection",
          "You cannot disable your own account",
        );
      }
      if (
        existing.role === "administrator" &&
        Boolean(existing.enabled) &&
        (nextRole !== "administrator" || !nextEnabled) &&
        this.countEnabledAdministrators() <= 1
      ) {
        throw new UserAdministrationError(
          "last_administrator",
          "At least one enabled administrator account is required",
        );
      }
      this.connection
        .prepare(
          `UPDATE users
           SET username = ?, role = ?, enabled = ?,
               token_version = token_version + 1
           WHERE id = ?`,
        )
        .run(
          input.username ?? existing.username,
          nextRole,
          nextEnabled ? 1 : 0,
          id,
        );
      return mapUser(this.getUserById(id) as UserRow);
    })();
  }

  deleteUser(id: string, actorId: string): UserSummary | undefined {
    return this.connection.transaction(() => {
      const existing = this.getUserById(id);
      if (!existing) return undefined;
      if (id === actorId) {
        throw new UserAdministrationError(
          "self_protection",
          "You cannot delete your own account",
        );
      }
      if (
        existing.role === "administrator" &&
        Boolean(existing.enabled) &&
        this.countEnabledAdministrators() <= 1
      ) {
        throw new UserAdministrationError(
          "last_administrator",
          "At least one enabled administrator account is required",
        );
      }
      this.connection
        .prepare(
          "UPDATE alarm_events SET acknowledged_by = NULL WHERE acknowledged_by = ?",
        )
        .run(id);
      this.connection
        .prepare(
          "UPDATE system_alerts SET acknowledged_by = NULL WHERE acknowledged_by = ?",
        )
        .run(id);
      this.connection
        .prepare(
          `INSERT OR REPLACE INTO user_revocations (user_id, revoked_at)
           VALUES (?, ?)`,
        )
        .run(id, new Date().toISOString());
      this.connection.prepare("DELETE FROM users WHERE id = ?").run(id);
      return mapUser(existing);
    })();
  }

  private countEnabledAdministrators(): number {
    return (
      this.connection
        .prepare(
          `SELECT COUNT(*) AS count
           FROM users
           WHERE role = 'administrator' AND enabled = 1`,
        )
        .get() as CountRow
    ).count;
  }

