  getGroupCurrentValues(): Array<{register_id: string; value: number}> {
    return this.connection.prepare(
      `SELECT r.id as register_id, 
              (SELECT latest.value FROM readings latest 
               JOIN registers reg ON latest.register_id = reg.id 
               WHERE latest.register_id = r.id 
               ORDER BY latest.timestamp DESC LIMIT 1) as value
       FROM registers r`
    ).all() as any[];
  }

  evaluateGroupAlarms(): void {
    const groups = this.listAlarmGroups();
    
    for (const group of groups) {
      const members = this.listGroupMembers(group.id);
      if (members.length === 0) continue;
      
      const rules = this.connection.prepare(
        'SELECT * FROM alarm_group_rules WHERE group_id = ? AND enabled = 1'
      ).all(group.id) as any[];
      
      // Get current values for all members
      const registerIds = members.map(m => m.register_id);
      if (registerIds.length === 0) continue;
      
      const placeholders = registerIds.map(() => '?').join(',');
      const currentValues = this.connection.prepare(
        `SELECT r.id as register_id, 
                (SELECT latest.value FROM readings latest 
                 JOIN registers reg ON latest.register_id = reg.id 
                 WHERE latest.register_id = r.id 
                 ORDER BY latest.timestamp DESC LIMIT 1) as value
         FROM registers r WHERE r.id IN (${placeholders})`
      ).all(...registerIds) as any[];
      
      const valuesMap = new Map(currentValues.map(cv => [cv.register_id, cv.value]));
      
      // Evaluate each rule against all members
      for (const rule of rules) {
        let triggered = false;
        let triggeringValue: number | null = null;
        let triggerMessage = '';
        
        for (const member of members) {
          const value = valuesMap.get(member.register_id);
          if (value === undefined || value === null) continue;
          
          switch (rule.condition) {
            case 'hi':
              if (value > rule.threshold_hi!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} exceeds HI threshold (${rule.threshold_hi})`;
              }
              break;
            case 'lo':
              if (value < rule.threshold_lo!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} below LO threshold (${rule.threshold_lo})`;
              }
              break;
            case 'hii':
              if (value > rule.threshold_hi!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} exceeds HII threshold (${rule.threshold_hi})`;
              }
              break;
            case 'lolo':
              if (value < rule.threshold_lo!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} below LOLO threshold (${rule.threshold_lo})`;
              }
              break;
            case 'above':
              if (value > rule.threshold_hi!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} above threshold (${rule.threshold_hi})`;
              }
              break;
            case 'below':
              if (value < rule.threshold_lo!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} below threshold (${rule.threshold_lo})`;
              }
              break;
            case 'outside':
              if (value > rule.threshold_hi! || value < rule.threshold_lo!) {
                triggered = true;
                triggeringValue = value;
                triggerMessage = `Group "${group.name}" - ${member.register_id} outside range [${rule.threshold_lo}, ${rule.threshold_hi}]`;
              }
              break;
          }
          
          if (triggered) break; // Trigger on first violation
        }
        
        if (triggered && triggeringValue !== null) {
          const existingAlarm = this.connection.prepare(
            'SELECT id FROM alarm_events WHERE rule_id = ? AND cleared_at IS NULL'
          ).get(rule.id) as any;
          
          if (!existingAlarm) {
            this.openGroupAlarm(rule.id, group.name, triggeringValue, triggerMessage);
          } else {
            this.updateActiveAlarm(existingAlarm.id, triggeringValue);
          }
        } else {
          // Clear alarm if condition is no longer met
          const existingAlarm = this.connection.prepare(
            'SELECT id FROM alarm_events WHERE rule_id = ? AND cleared_at IS NULL'
          ).get(rule.id) as any;
          
          if (existingAlarm) {
            this.clearAlarm(existingAlarm.id, 0);
          }
        }
      }
    }
  }

  openGroupAlarm(ruleId: string, groupName: string, value: number, message: string): void {
    const id = createId("alm");
    const now = new Date().toISOString();
    this.connection.prepare(
      `INSERT INTO alarm_events (id, rule_id, register_id, opened_value, current_value, opened_at, message) 
       VALUES (?, ?, 'group:${groupName}', ?, ?, ?, ?)`
    ).run(id, ruleId, value, value, now, message);
  }

