    if (updates.name) { sets.push('name = ?'); values.push(updates.name); }
    if (updates.severity) { sets.push('severity = ?'); values.push(updates.severity); }
    if (updates.condition) { sets.push('condition = ?'); values.push(updates.condition); }
    if (updates.thresholdHigh !== undefined) { sets.push('threshold_high = ?'); values.push(updates.thresholdHigh); }
    if (updates.thresholdLow !== undefined) { sets.push('threshold_low = ?'); values.push(updates.thresholdLow); }
    if (updates.aggregationType) { sets.push('aggregation_type = ?'); values.push(updates.aggregationType); }
    if (updates.deadband !== undefined) { sets.push('deadband = ?'); values.push(updates.deadband); }
